/* Automations: "Could not create the flow" (Postgres 23514, a check refused the row). The live email_flows table carries a check on trigger_type or status that no file in this repository made, from before the First order and Leaves checkout triggers existed, so choosing either template was refused. This drops every check on email_flows that names trigger_type or status, whatever it is called, and adds the two the app writes against: the four triggers (lib/automations/flow-model.ts TriggerType) plus the two older names rows may still carry, and draft, active or paused. NOT VALID: a new or changed row is checked, rows already there are left alone. Safe to run again. */
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND contype = 'c' AND (pg_get_constraintdef(oid) ILIKE '%trigger_type%' OR pg_get_constraintdef(oid) ILIKE '%status%') LOOP EXECUTE format('ALTER TABLE public.email_flows DROP CONSTRAINT %I', c.conname); RAISE NOTICE 'email_flows: dropped the old check %', c.conname; END LOOP; END $$;
ALTER TABLE public.email_flows ADD CONSTRAINT email_flows_trigger_type_check CHECK (trigger_type IN ('new_subscriber', 'purchase', 'first_purchase', 'abandoned_checkout', 'tag_added', 'manual')) NOT VALID;
ALTER TABLE public.email_flows ADD CONSTRAINT email_flows_status_check CHECK (status IN ('draft', 'active', 'paused')) NOT VALID;
NOTIFY pgrst, 'reload schema';
/* One row: both read true, and the old check is gone. */
SELECT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND conname = 'email_flows_trigger_type_check' AND pg_get_constraintdef(oid) ILIKE '%abandoned_checkout%' AND pg_get_constraintdef(oid) ILIKE '%first_purchase%') AS triggers_allowed, EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND conname = 'email_flows_status_check') AS statuses_allowed, (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.email_flows'::regclass AND contype = 'c') AS checks_on_email_flows;
